#!/usr/bin/env node
// Builds bundle/mineflayer-agent, the one-skill bundle, from skills/:
// mf-basics is its SKILL.md, each other skill becomes references/<name>.md,
// and each one's intro.md is its paragraph in the bundle's "Guides".
// Run after changing a skill; test/bundle.test.mjs checks it is up to date.
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const TOP = "mf-basics";
const NAME = "mineflayer-agent";
const ORDER = [
  "mineflayer-programs",
  "mineflayer-navigation",
  "mineflayer-surroundings",
  "mineflayer-items",
  "mineflayer-survival",
];
const DESCRIPTION =
  "Play Minecraft Java through a real Mineflayer bot, all in one skill: running the character and programs with mf, the game log, the work loop, the example programs, and guides on writing programs and setup, moving, looking at the world, items and survival. Use it instead of the separate mf-basics and mineflayer-* skills.";

const body = (text) => text.replace(/^---\n[^]*?\n---\n+/, "");
const generated = (source) =>
  `<!-- Generated by scripts/build-bundle.mjs from skills/${source}; edit that and run npm run build:bundle. -->\n\n`;

/** Rewrites links and skill names for the bundle's SKILL.md or one of its references. */
function relink(text, names, { inReferences }) {
  const up = inReferences ? "../../../" : "../../";
  const ref = (name) => (inReferences ? `${name}.md` : `references/${name}.md`);
  return text
    .replace(/\]\(\.\.\/\.\.\//g, `](${up}`)
    .replace(/the `(mineflayer-[a-z]+)` skill/g, (m, name) =>
      names.includes(name) ? `[${name}](${ref(name)})` : m,
    )
    .replace(
      /see `mf-basics`/g,
      inReferences ? "see [SKILL.md](../SKILL.md)" : "see above",
    );
}

export async function buildBundle() {
  // The order of the bundle's guides; every other skill in skills/ must be listed.
  const dirs = ORDER;
  const found = (await readdir(join(root, "skills"), { withFileTypes: true }))
    .filter((d) => d.isDirectory() && d.name !== TOP)
    .map((d) => d.name);
  const missing = found.filter((name) => !ORDER.includes(name));
  if (missing.length)
    throw new Error(`Not in the bundle order: ${missing.join(", ")}`);
  const files = new Map();
  const guides = [];
  for (const name of dirs) {
    const skill = await readFile(
      join(root, "skills", name, "SKILL.md"),
      "utf8",
    );
    const intro = (
      await readFile(join(root, "skills", name, "intro.md"), "utf8")
    ).trim();
    files.set(
      join("references", `${name}.md`),
      generated(`${name}/SKILL.md`) +
        relink(body(skill), dirs, { inReferences: true }),
    );
    guides.push(intro);
  }
  const top = body(
    await readFile(join(root, "skills", TOP, "SKILL.md"), "utf8"),
  );
  const start = top.indexOf("## The other skills");
  if (start < 0)
    throw new Error(
      `skills/${TOP}/SKILL.md has no "## The other skills" section`,
    );
  const next = top.indexOf("\n## ", start + 1);
  const main =
    top.slice(0, start) +
    "## Guides\n\nRead the one you need when you need it:\n\n" +
    guides.map((g) => `- ${g}`).join("\n") +
    "\n" +
    (next < 0 ? "" : top.slice(next));
  files.set(
    "SKILL.md",
    `---\nname: ${NAME}\ndescription: "${DESCRIPTION}"\n---\n\n` +
      generated(`${TOP}/SKILL.md and the others`) +
      relink(main, dirs, { inReferences: false }),
  );
  return files;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const out = join(root, "bundle", NAME);
  await rm(out, { recursive: true, force: true });
  for (const [path, text] of await buildBundle()) {
    await mkdir(dirname(join(out, path)), { recursive: true });
    await writeFile(join(out, path), text);
  }
  console.log(`wrote bundle/${NAME}`);
}
